import{_ as s,o as e,c as a,ag as o}from"./chunks/framework.7He2WLS4.js";const u=JSON.parse('{"title":"Chaining Proxies","description":"","frontmatter":{},"headers":[],"relativePath":"guides/chaining-proxies.md","filePath":"guides/chaining-proxies.md","lastUpdated":1772297611000}'),r={name:"guides/chaining-proxies.md"};function n(i,t,l,p,h,d){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="chaining-proxies" tabindex="-1">Chaining Proxies <a class="header-anchor" href="#chaining-proxies" aria-label="Permalink to &quot;Chaining Proxies&quot;">​</a></h1><p><strong>Difficulty:</strong> Advanced | <strong>Time:</strong> 10 minutes</p><p>This tutorial explains how to configure NectoProxy to route its outbound traffic through an upstream proxy server. This is essential in corporate environments with mandatory HTTP proxies, for routing traffic through SOCKS5 tunnels, or for layered debugging setups.</p><h2 id="how-proxy-chaining-works" tabindex="-1">How Proxy Chaining Works <a class="header-anchor" href="#how-proxy-chaining-works" aria-label="Permalink to &quot;How Proxy Chaining Works&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser  --&gt;  NectoProxy  --&gt;  Upstream Proxy  --&gt;  Internet</span></span>
<span class="line"><span>  (client)    (MITM + UI)      (corporate/SSH)    (target server)</span></span></code></pre></div><p>Without chaining, NectoProxy connects directly to target servers. With chaining, NectoProxy routes all outbound requests through the configured upstream proxy. NectoProxy still performs MITM decryption and provides the full debugging UI -- the upstream proxy simply handles the final hop.</p><h2 id="supported-upstream-proxy-types" tabindex="-1">Supported Upstream Proxy Types <a class="header-anchor" href="#supported-upstream-proxy-types" aria-label="Permalink to &quot;Supported Upstream Proxy Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Protocol</th><th>Description</th><th>Use Case</th></tr></thead><tbody><tr><td><strong>HTTP</strong></td><td>Standard HTTP proxy (CONNECT for HTTPS)</td><td>Corporate proxies, Squid, other HTTP proxies</td></tr><tr><td><strong>HTTPS</strong></td><td>HTTP proxy over TLS</td><td>Encrypted proxy connections</td></tr><tr><td><strong>SOCKS4</strong></td><td>SOCKS version 4 proxy</td><td>Legacy SSH tunnels</td></tr><tr><td><strong>SOCKS5</strong></td><td>SOCKS version 5 proxy (with optional auth)</td><td>SSH tunnels, Tor, VPN gateways</td></tr></tbody></table><h2 id="scenario-1-corporate-http-proxy" tabindex="-1">Scenario 1: Corporate HTTP Proxy <a class="header-anchor" href="#scenario-1-corporate-http-proxy" aria-label="Permalink to &quot;Scenario 1: Corporate HTTP Proxy&quot;">​</a></h2><p>Your company requires all internet traffic to pass through a corporate proxy. You want to use NectoProxy for debugging, but it needs to chain through the corporate proxy to reach external servers.</p><h3 id="configuration-steps" tabindex="-1">Configuration Steps <a class="header-anchor" href="#configuration-steps" aria-label="Permalink to &quot;Configuration Steps&quot;">​</a></h3><ol><li><p>Open the NectoProxy Web UI at <code>http://localhost:8889</code>.</p></li><li><p>Click the <strong>gear icon</strong> to open Settings.</p></li><li><p>In the Proxy Settings section, click <strong>Configure</strong> next to <strong>Upstream Proxy</strong>.</p></li><li><p>In the Upstream Proxy panel, configure:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Enabled</strong></td><td>On</td></tr><tr><td><strong>Protocol</strong></td><td>HTTP</td></tr><tr><td><strong>Host</strong></td><td><code>proxy.corporate.com</code></td></tr><tr><td><strong>Port</strong></td><td><code>8080</code></td></tr></tbody></table></li><li><p>If your corporate proxy requires authentication:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Username</strong></td><td><code>your-username</code></td></tr><tr><td><strong>Password</strong></td><td><code>your-password</code></td></tr></tbody></table></li><li><p>Click <strong>Save</strong>.</p></li></ol><p>All outbound traffic from NectoProxy now routes through <code>proxy.corporate.com:8080</code>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can find your corporate proxy settings in your system&#39;s proxy configuration, your company&#39;s IT documentation, or by checking environment variables like <code>HTTP_PROXY</code> and <code>HTTPS_PROXY</code>.</p></div><h2 id="scenario-2-socks5-proxy-ssh-tunnel" tabindex="-1">Scenario 2: SOCKS5 Proxy (SSH Tunnel) <a class="header-anchor" href="#scenario-2-socks5-proxy-ssh-tunnel" aria-label="Permalink to &quot;Scenario 2: SOCKS5 Proxy (SSH Tunnel)&quot;">​</a></h2><p>You have an SSH tunnel providing SOCKS5 access to a remote network. You want to use NectoProxy to debug traffic flowing through that tunnel.</p><h3 id="setting-up-the-ssh-tunnel" tabindex="-1">Setting Up the SSH Tunnel <a class="header-anchor" href="#setting-up-the-ssh-tunnel" aria-label="Permalink to &quot;Setting Up the SSH Tunnel&quot;">​</a></h3><p>First, create a SOCKS5 proxy via SSH:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Create a SOCKS5 proxy on local port 1080</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user@remote-server.example.com</span></span></code></pre></div><p>This creates a SOCKS5 proxy listening on <code>localhost:1080</code>.</p><h3 id="configure-nectoproxy" tabindex="-1">Configure NectoProxy <a class="header-anchor" href="#configure-nectoproxy" aria-label="Permalink to &quot;Configure NectoProxy&quot;">​</a></h3><ol><li><p>Open Settings &gt; Upstream Proxy.</p></li><li><p>Configure:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Enabled</strong></td><td>On</td></tr><tr><td><strong>Protocol</strong></td><td>SOCKS5</td></tr><tr><td><strong>Host</strong></td><td><code>127.0.0.1</code></td></tr><tr><td><strong>Port</strong></td><td><code>1080</code></td></tr></tbody></table></li><li><p>Click <strong>Save</strong>.</p></li></ol><p>Now all traffic from NectoProxy routes through your SSH tunnel, and you can inspect it in the Web UI.</p><details class="details custom-block"><summary>Using Tor as an Upstream Proxy</summary><p>Tor&#39;s local proxy uses SOCKS5 on port 9050 by default. To route NectoProxy traffic through Tor:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Protocol</strong></td><td>SOCKS5</td></tr><tr><td><strong>Host</strong></td><td><code>127.0.0.1</code></td></tr><tr><td><strong>Port</strong></td><td><code>9050</code></td></tr></tbody></table><p>Note that routing through Tor adds significant latency. Also be aware that Tor exit nodes may block or modify traffic. This setup is primarily useful for testing how your application behaves when accessed through Tor.</p></details><h2 id="scenario-3-bypass-rules-for-internal-domains" tabindex="-1">Scenario 3: Bypass Rules for Internal Domains <a class="header-anchor" href="#scenario-3-bypass-rules-for-internal-domains" aria-label="Permalink to &quot;Scenario 3: Bypass Rules for Internal Domains&quot;">​</a></h2><p>When using an upstream proxy, you may want some traffic to bypass the proxy and connect directly. For example, internal services on your company&#39;s network may not be reachable through the corporate proxy.</p><h3 id="configure-bypass-rules" tabindex="-1">Configure Bypass Rules <a class="header-anchor" href="#configure-bypass-rules" aria-label="Permalink to &quot;Configure Bypass Rules&quot;">​</a></h3><p>In the Upstream Proxy configuration panel:</p><ol><li>Locate the <strong>Bypass Rules</strong> section.</li><li>Add domains or patterns that should skip the upstream proxy:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>localhost</span></span>
<span class="line"><span>127.0.0.1</span></span>
<span class="line"><span>*.internal.company.com</span></span>
<span class="line"><span>10.0.0.*</span></span>
<span class="line"><span>192.168.*.*</span></span>
<span class="line"><span>*.local</span></span></code></pre></div><p>Each line is a pattern. Wildcards (<code>*</code>) are supported.</p><h3 id="how-bypass-works" tabindex="-1">How Bypass Works <a class="header-anchor" href="#how-bypass-works" aria-label="Permalink to &quot;How Bypass Works&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Request Target</th><th style="text-align:center;">Upstream Proxy?</th><th>Why</th></tr></thead><tbody><tr><td><code>api.example.com</code></td><td style="text-align:center;">Yes</td><td>Does not match any bypass rule</td></tr><tr><td><code>app.internal.company.com</code></td><td style="text-align:center;">No</td><td>Matches <code>*.internal.company.com</code></td></tr><tr><td><code>localhost:3000</code></td><td style="text-align:center;">No</td><td>Matches <code>localhost</code></td></tr><tr><td><code>10.0.0.5:8080</code></td><td style="text-align:center;">No</td><td>Matches <code>10.0.0.*</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Bypass rules use simple string matching with wildcard support. They match against the hostname (not the full URL). If your internal services use IP addresses, add both the IP patterns and the hostnames to the bypass list.</p></div><h2 id="verifying-the-configuration" tabindex="-1">Verifying the Configuration <a class="header-anchor" href="#verifying-the-configuration" aria-label="Permalink to &quot;Verifying the Configuration&quot;">​</a></h2><p>After configuring the upstream proxy, verify it works:</p><ol><li>Open a website through your browser (proxied through NectoProxy).</li><li>Check the NectoProxy traffic list -- requests should appear normally.</li><li>If the upstream proxy is unreachable, you will see <code>502 Bad Gateway</code> errors in the traffic list.</li></ol><h3 id="troubleshooting-chain-issues" tabindex="-1">Troubleshooting Chain Issues <a class="header-anchor" href="#troubleshooting-chain-issues" aria-label="Permalink to &quot;Troubleshooting Chain Issues&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely Cause</th><th>Solution</th></tr></thead><tbody><tr><td>All requests return 502</td><td>Upstream proxy is unreachable</td><td>Verify host and port, check if proxy is running</td></tr><tr><td>Authentication errors (407)</td><td>Wrong credentials</td><td>Double-check username and password</td></tr><tr><td>Some sites work, others do not</td><td>Upstream proxy blocks certain domains</td><td>Check upstream proxy&#39;s allow/deny lists</td></tr><tr><td>HTTPS sites fail but HTTP works</td><td>Upstream proxy does not support CONNECT</td><td>Switch to SOCKS5 or contact proxy administrator</td></tr><tr><td>Extremely slow connections</td><td>Proxy chain adds latency</td><td>Expected with multi-hop routing; consider bypassing for non-essential domains</td></tr></tbody></table><h2 id="settings-api" tabindex="-1">Settings API <a class="header-anchor" href="#settings-api" aria-label="Permalink to &quot;Settings API&quot;">​</a></h2><p>You can also configure the upstream proxy programmatically:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Configure HTTP upstream proxy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8889/api/upstream-proxy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;enabled&quot;: true,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;type&quot;: &quot;http&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;host&quot;: &quot;proxy.corporate.com&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;port&quot;: 8080,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;auth&quot;: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;username&quot;: &quot;user&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;password&quot;: &quot;pass&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    },</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;bypassRules&quot;: [&quot;localhost&quot;, &quot;*.internal.com&quot;]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Disable upstream proxy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8889/api/upstream-proxy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;enabled&quot;: false}&#39;</span></span></code></pre></div><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Test bypass rules carefully.</strong> An incorrect bypass rule might route internal traffic through the external proxy (a security concern) or fail to route external traffic through the proxy (a connectivity issue).</li><li><strong>Use SOCKS5 over SOCKS4</strong> when possible. SOCKS5 supports authentication and DNS resolution through the proxy, which are important for security and functionality.</li><li><strong>Monitor for 407 errors.</strong> A <code>407 Proxy Authentication Required</code> response means the upstream proxy rejected your credentials.</li><li><strong>Chain order matters.</strong> Your browser connects to NectoProxy, which connects to the upstream proxy. NectoProxy handles MITM decryption regardless of the upstream proxy -- the upstream proxy only sees encrypted CONNECT tunnels for HTTPS traffic.</li></ul>`,44)])])}const g=s(r,[["render",n]]);export{u as __pageData,g as default};
